import * as path from "path";
import {
  readdir,
  readFileSync,
  statSync,
  writeFileSync,
  mkdirSync,
  existsSync,
} from "fs";
import * as ts from "typescript";
import { airbus as tokens } from "@airbus/design-tokens";

const OUTPUT_CSV = "reports/tokens_usage.csv";
const OUTPUT_JSON = "reports/tokens_usage.json";
const RAW_USAGE: { [key: string]: string[] } = {};
let tokenCountTotal = 0,
  tokenCountUnique = 0;

// get object nested value from a string path
const resolveObjectValue = (obj: any, path: string) => {
  var properties = path.split(".");
  return properties.reduce((prev, curr) => prev?.[curr], obj);
};

// find full path to color palette token given a hex color value
const getAliasedColorTokenPath = (colorValue: string) => {
  const palette = tokens.color.palette as any;
  const paletteKeys = Object.keys(palette);
  let colorTokenPath: string = "";
  paletteKeys.forEach((col) => {
    if (palette[col] === colorValue) colorTokenPath = `color.palette.${col}`;
    const shadeKeys = Object.keys(palette[col]);
    shadeKeys.forEach((shade) => {
      if (palette[col][shade] === colorValue)
        colorTokenPath = `color.palette.${col}.${shade}`;
    });
  });
  return colorTokenPath;
};

// parse one component
const parseComponent = (componentDir: string) => {
  const componentName: string = componentDir.split("/").pop() as string;
  // console.log("--", componentName?.toUpperCase());
  tokenCountTotal = 0;
  tokenCountUnique = 0;

  const sourceFile = ts.createSourceFile(
    "component.ts",
    readFileSync(`./${componentDir}/index.ts`, "utf8"),
    ts.ScriptTarget.Latest
  );

  // save raw token usage for this component
  const saveUsage = (tokenName: string) => {
    // console.log("saveUsage", tokenName);
    tokenCountTotal++;
    if (RAW_USAGE[tokenName] === undefined) {
      tokenCountUnique++;
      RAW_USAGE[tokenName] = [componentName];
    } else if (RAW_USAGE[tokenName].indexOf(componentName) < 0) {
      tokenCountUnique++;
      RAW_USAGE[tokenName].push(componentName);
    }
  };

  // recursively parse AST nodes
  const parseChildNode = (node: ts.Node) => {
    const coreTokensCategories = [
      "font.size",
      "font.weight",
      "font.lineheight",
      "elevation.zindex",
      "elevation.level",
    ];
    const colorAliasCategories = [
      "color.border",
      "color.dimmed",
      "color.saturated",
      "color.surface",
      "color.text",
    ];

    let expression: ts.LeftHandSideExpression;
    let nodeText: string;
    let nodeValue: string;

    switch (node.kind) {
      case ts.SyntaxKind.ElementAccessExpression:
        // parse expressions like "color.palette.primaryblue[90]"
        expression = (node as ts.ElementAccessExpression).expression;
        const argumentExpression = (node as ts.ElementAccessExpression)
          .argumentExpression;

        // getFullText will return "color.palette.primaryBlue" for example
        nodeText = expression.getFullText(sourceFile).trim();
        nodeValue = argumentExpression.getText(sourceFile).replace(/["']/g, "");
        if (
          nodeText.indexOf("color.palette") >= 0 ||
          nodeText === "size.spacing" ||
          nodeText.indexOf("elevation.level") >= 0 ||
          ((nodeText.indexOf("font.size") >= 0 ||
            nodeText.indexOf("font.lineheight") >= 0) &&
            nodeValue !== "size")
        ) {
          saveUsage(`${nodeText}.${nodeValue}`);
        } else {
          // console.log(
          //   "[ElementAccessExpression] Skipped",
          //   nodeText,
          //   ":",
          //   nodeValue
          // );
        }
        break;
      case ts.SyntaxKind.PropertyAccessExpression:
        // parse expressions like "color.palette.white"
        expression = (node as ts.PropertyAccessExpression).expression;
        nodeValue = (node as ts.PropertyAccessExpression).name.getText(
          sourceFile
        );
        nodeText = expression.getFullText(sourceFile).trim();
        console.log("[PropertyAccessExpression]", nodeText, ":", nodeValue);
        if (nodeText.indexOf("color.palette") >= 0) {
          // ignore color tokens with shades
          if (
            typeof resolveObjectValue(tokens, `${nodeText}.${nodeValue}`) !==
            "string"
          )
            break;
          saveUsage(`${nodeText}.${nodeValue}`);
        } else if (colorAliasCategories.some((cat) => nodeText.includes(cat))) {
          // ALIASED color token category
          console.log("resolve alias", nodeText, nodeValue);
          const col = resolveObjectValue(tokens, `${nodeText}.${nodeValue}`);
          if (!col) break;
          if (col.light !== undefined) {
            saveUsage(getAliasedColorTokenPath(col.light));
            saveUsage(getAliasedColorTokenPath(col.dark));
          } else {
            const colorAlias = getAliasedColorTokenPath(col);
            if (colorAlias !== "") saveUsage(colorAlias);
          }
        } else if (
          coreTokensCategories.some((cat) => nodeText.includes(cat))
        ) {
          saveUsage(`${nodeText}.${nodeValue}`);
        } else if (nodeText === "elevation" && nodeValue.includes("level")) {
          saveUsage(`${nodeText}.${nodeValue}`);
        } else {
          // console.log(
          //   "[PropertyAccessExpression] Skipped",
          //   nodeText,
          //   ":",
          //   nodeValue
          // );
        }
        break;
    }
    ts.forEachChild(node, parseChildNode);
  };

  ts.forEachChild(sourceFile, parseChildNode);
  console.log(
    "--",
    componentName?.toUpperCase(),
    `- ${tokenCountUnique} tokens (found:${tokenCountTotal})`
  );
};

// list subdirectories of specified root dir
var getSubdirectories = (rootdir: string, cb: Function) => {
  readdir(rootdir, (err, files) => {
    if (err) throw err;
    var dirs = files
      .map((filename) => path.join(rootdir, filename))
      .filter((pathname) => statSync(pathname).isDirectory());
    return cb(dirs);
  });
};

// format RAW token usage as json
var formatJSONOutput = () => {
  const output: { [key: string]: any } = {};
  // sort tokens alphabetically
  const sortedTokens = Object.fromEntries(Object.entries(RAW_USAGE).sort());
  // then parse each token by full path
  const tokenKeys = Object.keys(sortedTokens);
  tokenKeys.forEach((tokenKey) => {
    const path = tokenKey.split(".");
    let outputNode = output;
    for (let i = 0; i < path.length; i++) {
      if (i === path.length - 1) {
        // save leaf value
        outputNode[path[i]] = RAW_USAGE[tokenKey];
      } else {
        // initialize json tree of objects
        if (!outputNode[path[i]]) outputNode[path[i]] = {};
        outputNode = outputNode[path[i]];
      }
    }
  });

  return JSON.stringify(output, null, 2);
};

var formatCSVOutput = () => {
  const rows: string[] = [];
  // sort tokens alphabetically
  const sortedTokens = Object.fromEntries(Object.entries(RAW_USAGE).sort());
  // then parse each token by full path
  const tokenKeys = Object.keys(sortedTokens);
  tokenKeys.forEach((tokenKey) => {
    rows.push(`${tokenKey},${RAW_USAGE[tokenKey].join(",")}`);
  });
  return rows.join("\n");
};

getSubdirectories("./src/elements", (dirs: string[]) => {
  // parseComponent(dirs[13]);
  dirs.forEach((dir) => parseComponent(dir));
  // create folder if not exists
  if (!existsSync(OUTPUT_JSON)) mkdirSync("reports", { recursive: true });
  writeFileSync(OUTPUT_JSON, formatJSONOutput());
  writeFileSync(OUTPUT_CSV, formatCSVOutput());
});
